import{_ as t,o as a,c as o,a2 as n}from"./chunks/framework.mRCPFc5l.js";const u=JSON.parse('{"title":"API credentials","description":"Generate and securely manage credentials for the API.","frontmatter":{"title":"API credentials","description":"Generate and securely manage credentials for the API."},"headers":[],"relativePath":"en/integrationen/api-zugangsdaten.md","filePath":"en/integrationen/api-zugangsdaten.md","lastUpdated":1787319236000}'),r={name:"en/integrationen/api-zugangsdaten.md"};function i(s,e,l,d,c,h){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="api-credentials" tabindex="-1">API credentials <a class="header-anchor" href="#api-credentials" aria-label="Permalink to &quot;API credentials&quot;">​</a></h1><p>To access the API, your own applications need <strong>API credentials</strong>.</p><p>You&#39;ll find them under <strong>Profile &amp; settings → API credentials</strong>.</p><div class="danger custom-block"><p class="custom-block-title">Personal and far-reaching</p><blockquote><p><em>These are your personal API credentials. They are needed to use the API. Your personal API credentials grant access to <strong>all data in your Spaces</strong>. Only share these credentials with third-party services and applications you trust.</em></p></blockquote><p>Two things about this matter:</p><ol><li><strong>Personal, not tied to a Space.</strong> The credentials reach as far as your own access — across <strong>all</strong> your Spaces, even ones unrelated to the project at hand.</li><li><strong>They&#39;re tied to your account.</strong> If someone leaves the company and their account gets deleted, every integration built with those credentials stops working.</li></ol></div><h2 id="creating-credentials" tabindex="-1">Creating credentials <a class="header-anchor" href="#creating-credentials" aria-label="Permalink to &quot;Creating credentials&quot;">​</a></h2><ol><li>Click <strong>Create credentials</strong>.</li><li>Give them a name under <em>Choose a name for your credentials</em>.</li><li>Choose the permission under <em>These credentials grant:</em>.</li><li>Confirm with <strong>Create</strong>.</li></ol><h3 id="permission" tabindex="-1">Permission <a class="header-anchor" href="#permission" aria-label="Permalink to &quot;Permission&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Choice</th><th>Scope</th></tr></thead><tbody><tr><td><strong>Admin</strong></td><td><em>Full access to your Spaces</em></td></tr><tr><td><strong>Read only</strong></td><td><em>Read-only access to your Spaces</em></td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">When in doubt, &quot;Read only&quot;</p><p>For reports, evaluations, and data exports, read access is enough. Choose <em>Admin</em> only when the application genuinely needs to write.</p><p>A read error in a script with read-only access costs nothing. The same error with full access can overwrite data.</p></div><div class="tip custom-block"><p class="custom-block-title">Separate credentials per application</p><p>Don&#39;t create one key for everything — create one per application, with a descriptive name. That way you can revoke individual ones without disabling everything else.</p></div><h2 id="visible-only-once" tabindex="-1">Visible only once <a class="header-anchor" href="#visible-only-once" aria-label="Permalink to &quot;Visible only once&quot;">​</a></h2><div class="danger custom-block"><p class="custom-block-title">Note them down immediately</p><p>After creation, this appears:</p><blockquote><p><strong>Your credentials are available</strong></p><p><strong>Save your authorization key and your password now.</strong></p><p><em>This is the only time the credentials can be viewed or downloaded. They cannot be recovered later. However, you can delete your API credentials at any time and generate new ones.</em></p></blockquote><p>The credentials consist of an <strong>authorization key</strong> and a <strong>password</strong>.</p><p>Store both in a password manager — <strong>not</strong> in a text file, a chat, or an email.</p></div><p>If something gets lost, delete the credentials and generate new ones. The integration will then need to be updated.</p><h2 id="security" tabindex="-1">Security <a class="header-anchor" href="#security" aria-label="Permalink to &quot;Security&quot;">​</a></h2><div class="danger custom-block"><p class="custom-block-title">Where credentials don&#39;t belong</p><ul><li><strong>Not in public repositories.</strong> Automated scanners find keys like this within minutes.</li><li><strong>Not in frontend code.</strong> Anything that runs in the browser can be inspected.</li><li><strong>Not in chats, tickets, or slides.</strong></li><li><strong>Not in screenshots.</strong></li></ul></div><div class="tip custom-block"><p class="custom-block-title">Clean up regularly</p><p>Go through your list of credentials and delete what&#39;s no longer needed. A forgotten key stays valid until someone removes it.</p></div><h2 id="how-to-recognize-api-access" tabindex="-1">How to recognize API access <a class="header-anchor" href="#how-to-recognize-api-access" aria-label="Permalink to &quot;How to recognize API access&quot;">​</a></h2><p>Entries created via the API show the value <strong>API credentials</strong> in the <strong>Created by</strong> column, instead of a person&#39;s name.</p><p>In the <a href="/en/grids/versionsverlauf">version history</a>, corresponding changes appear as <strong>System or Flow</strong>.</p><div class="tip custom-block"><p class="custom-block-title">Useful for troubleshooting</p><p>If a value changes unexpectedly, the version history quickly clarifies whether a person, a Flow, or a connected application is behind it.</p></div><h2 id="technical-details" tabindex="-1">Technical details <a class="header-anchor" href="#technical-details" aria-label="Permalink to &quot;Technical details&quot;">​</a></h2><p>For building an integration:</p><table tabindex="0"><thead><tr><th>Property</th><th>Value</th></tr></thead><tbody><tr><td>API version</td><td>2</td></tr><tr><td>Structure</td><td>resources reference each other via links</td></tr><tr><td>Authentication</td><td>authorization key and password</td></tr><tr><td>Space identifier</td><td>in <a href="/en/spaces/einstellungen">Space settings</a> under <em>Space identifier</em></td></tr><tr><td>Field identifiers</td><td>via <strong>Manage field key</strong> on the respective field</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">This documentation is not an API reference</p><p>A complete description of the available calls isn&#39;t part of this user documentation. For developer documentation, contact support via chat.</p></div><h2 id="do-you-really-need-the-api" tabindex="-1">Do you really need the API? <a class="header-anchor" href="#do-you-really-need-the-api" aria-label="Permalink to &quot;Do you really need the API?&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Often there&#39;s a simpler way</p><table tabindex="0"><thead><tr><th>Goal</th><th>Simpler path</th></tr></thead><tbody><tr><td>Pull in data from a system</td><td><a href="/en/grids/csv-import">CSV import</a></td></tr><tr><td>Hand data to a system</td><td><a href="/en/grids/csv-export">CSV export</a> or <a href="/en/integrationen/webhooks">Webhook</a></td></tr><tr><td>Call another system</td><td>Flow step <strong>HTTP request</strong></td></tr><tr><td>Start a Flow from outside</td><td><a href="/en/flows/webhook-trigger">Webhook trigger</a></td></tr><tr><td>Display data</td><td><a href="/en/seiten/portal-veroeffentlichen">Portal</a></td></tr></tbody></table><p>The API is worth it when your own application works with ApptiveGrid continuously, in both directions.</p></div><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/en/integrationen/ueberblick">Overview</a></li><li><a href="/en/integrationen/webhooks">Webhooks</a></li><li><a href="/en/erste-schritte/konto-und-anmeldung">Account and sign-in</a></li></ul>',28)])])}const g=t(r,[["render",i]]);export{u as __pageData,g as default};
